paddle3ReferenceFixtureSource:
"ui";
ui.layout(<vertical padding="24"><text id="result" text="Paddle v3 reference image" /></vertical>);
threads.start(function () {
    var out = {pageSize:Number(android.system.Os.sysconf(android.system.OsConstants._SC_PAGESIZE)), variant:"v3"};
    var image;
    try {
        var id = context.getResources().getIdentifier("paddle_ocr_test", "drawable", context.getPackageName());
        var bitmap = android.graphics.BitmapFactory.decodeResource(context.getResources(), id);
        var scaled = android.graphics.Bitmap.createScaledBitmap(bitmap, bitmap.getWidth() * 4, bitmap.getHeight() * 4, false);
        bitmap.recycle();
        image = Packages.org.autojs.autojs.core.image.ImageWrapper.ofBitmap(runtime, scaled);
        out.width = image.getWidth();
        out.height = image.getHeight();
        out.paddle = ocr.recognizeText(image, {mode:"paddle",variant:"v3"});
        out.ok = out.paddle.length > 0;
    } catch(e) {out.ok=false;out.error=String(e)+"\n"+e.stack;}
    finally {if(image)image.recycle();}
    files.write(new java.io.File(context.getExternalFilesDir(null), "samsung-paddle-reference.json").getAbsolutePath(), JSON.stringify(out));
    android.util.Log.i("Samsung16kReference",JSON.stringify(out));
    ui.run(function(){ui.result.setText(JSON.stringify(out));});
});
